import math


def family_init(ctx):
    ctx.at = ctx.indicator("atr", period=14)
    ctx.il = []            # trailing |r|/dollar-volume terms
    ctx.ih = []            # trailing ILLIQ history
    ctx.vh = []            # trailing ATR/close history
    ctx.vv = []            # trailing volumes
    ctx.armed = -1         # last bar on which the setup is still armed
    ctx.pi = None


def _pct(hist, x):
    n = len(hist)
    if n < 30:
        return None
    b = 0
    for h in hist:
        if h < x:
            b += 1
    return 100.0 * b / n


def signal(ctx, i):
    if i < 2:
        return 0
    c, pc = ctx.c[i], ctx.c[i - 1]
    h, l = ctx.h[i], ctx.l[i]
    v = ctx.v[i]
    a = ctx.at[i]
    if None in (c, pc, h, l, a) or c <= 0.0 or pc <= 0.0 or a <= 0.0:
        return 0
    v = float(v or 0.0)
    dv = c * v
    term = abs(math.log(c / pc)) / dv if dv > 0.0 else 0.0
    ctx.il.append(term)
    if len(ctx.il) > int(ctx.p.illiq_win):
        ctx.il.pop(0)
    ctx.vv.append(v)
    if len(ctx.vv) > int(ctx.p.vol_n):
        ctx.vv.pop(0)
    if len(ctx.il) < int(ctx.p.illiq_win):
        return 0
    illiq = 1e6 * sum(ctx.il) / len(ctx.il)
    rv = a / c

    PI = _pct(ctx.ih, illiq)
    PV = _pct(ctx.vh, rv)
    ctx.ih.append(illiq)
    if len(ctx.ih) > int(ctx.p.pct_hist):
        ctx.ih.pop(0)
    ctx.vh.append(rv)
    if len(ctx.vh) > int(ctx.p.pct_hist):
        ctx.vh.pop(0)
    ctx.pi = PI
    if PI is None or PV is None:
        return 0

    if PI >= float(ctx.p.p_i) and PV <= float(ctx.p.p_v):
        ctx.armed = i + max(1, int(ctx.p.arm_win))
    if i > ctx.armed:
        return 0
    rng = h - l
    if rng <= 0.0 or not ctx.vv:
        return 0
    mv = sum(ctx.vv) / len(ctx.vv)
    if mv <= 0.0 or v < float(ctx.p.vmult) * mv:
        return 0
    clv = (c - l) / rng
    lo = float(ctx.p.clv)
    if clv >= 1.0 - lo:
        ctx.armed = -1
        return 1
    if clv <= lo:
        ctx.armed = -1
        return -1
    return 0


def exit_signal(ctx, i):
    return ctx.pi is not None and ctx.pi < float(ctx.p.exit_pi)
